from common9 import *
def descriptive_point(x):
 if isinstance(x,dict):return {k:descriptive_point(v) for k,v in x.items() if k not in ('p_unadjusted','null','CI_direction')}
 if isinstance(x,list):return [descriptive_point(v) for v in x]
 return x
def table(rows,cols=None):
 if not rows:return 'No available rows; see skips and child outcomes.'
 d=pd.DataFrame(rows)
 if cols is not None:d=d[[k for k in cols if k in d]]
 def fmt(v):
  if isinstance(v,(list,dict)):return json.dumps(clean(v),ensure_ascii=False).replace('|','/')
  if v is None:return 'unavailable'
  if isinstance(v,(float,np.floating)):return f'{v:.6g}' if np.isfinite(v) else 'unavailable'
  return str(v).replace('|','/').replace('\n',' ')
 return '\n'.join(['| '+' | '.join(map(str,d.columns))+' |','| '+' | '.join(['---']*len(d.columns))+' |']+['| '+' | '.join(fmt(v) for v in row)+' |' for row in d.itertuples(index=False,name=None)])
